import { type DeviceState, defineDevice } from "@audio-ui/core/device";
import { GATE_KERNELS } from "@/components/audio-ui/devices/gate/kernels";
import { manifestWorklet } from "@/lib/manifest-worklet";

/**
 * A gate as a device: it lets a signal through above a threshold and turns it
 * down to a floor below it, with an attack and a release for how fast it opens
 * and closes, a hold for how long it stays open once the level has dropped, and
 * a look-ahead that delays the signal so the gate is open before a transient
 * arrives, and no panel and no audio in it. Its clean model takes a sidechain:
 * with `external` on, its level is the one of the signal connected to the
 * engine's `sidechain` input, so a kick can open a held chord. Its hysteresis
 * model is the gate of `@audio/dynamics-gate`, which closes only under a
 * lower threshold than the one it opens at.
 */
/** The longest look-ahead, in milliseconds: the delay the engine makes room for. */
export const MAX_LOOKAHEAD_MS = 10;

export const gateDevice = defineDevice({
  description:
    "Cleans up between sounds: above the threshold the signal passes, below it the signal is turned down to the floor. The attack and the release say how fast it opens and closes, the hold how long it stays open after the level drops, and the look-ahead delays the signal so the gate is open before a transient arrives. Its model is clean, the only one with the sidechain (with it on, the level it follows is the one of another signal), or hysteresis, which once open closes only when the level falls the hysteresis under the threshold, so a level around the threshold does not make it chatter.",
  id: "audioui.gate",
  // The look-ahead delays the signal, and so the device; off, the signal goes straight through.
  latency: (state) => (state.enabled ? state.lookaheadMs / 1000 : 0),
  name: "Gate",
  sidechain: true,
  parameters: [
    { default: true, id: "enabled", kind: "toggle", label: "On" },
    {
      default: "clean",
      id: "model",
      kind: "choice",
      label: "Model",
      options: [
        { label: "Clean", value: "clean" },
        { label: "Hysteresis", value: "hysteresis" },
      ],
    },
    {
      default: -36,
      id: "thresholdDb",
      label: "Threshold",
      max: 0,
      min: -70,
      step: 0.5,
      unit: "dB",
    },
    {
      default: 6,
      id: "hysteresisDb",
      label: "Hysteresis",
      max: 24,
      min: 0,
      step: 0.5,
      unit: "dB",
    },
    {
      default: -60,
      id: "floorDb",
      label: "Floor",
      max: 0,
      min: -80,
      step: 1,
      unit: "dB",
    },
    {
      default: 1,
      id: "attackMs",
      label: "Attack",
      max: 50,
      min: 0.1,
      scale: "log",
      step: 0.1,
      unit: "ms",
    },
    {
      default: 30,
      id: "holdMs",
      label: "Hold",
      max: 500,
      min: 0,
      step: 1,
      unit: "ms",
    },
    {
      default: 120,
      id: "releaseMs",
      label: "Release",
      max: 2000,
      min: 5,
      scale: "log",
      step: 1,
      unit: "ms",
    },
    {
      default: 0,
      id: "lookaheadMs",
      label: "Look-ahead",
      max: MAX_LOOKAHEAD_MS,
      min: 0,
      step: 0.5,
      unit: "ms",
    },
    { default: false, id: "external", kind: "toggle", label: "Sidechain" },
  ],
});

export type GateState = DeviceState<typeof gateDevice.parameters>;

const toGain = (db: number) => 10 ** (db / 20);

/** The controls a model does not use: the hysteresis for the clean one, the sidechain for the other. */
export function gateUnused(model: GateState["model"]) {
  return model === "clean"
    ? (["hysteresisDb"] as const)
    : (["external"] as const);
}

/** The numbers that go on the nodes for a state. Off, the gate is fully open. */
export function gateSettings(state: GateState) {
  const clean = state.model === "clean";
  // Only the clean model listens to a key.
  const external = clean && state.external;
  return {
    attack: state.attackMs / 1000,
    floor: state.enabled ? toGain(state.floorDb) : 1,
    hold: state.holdMs / 1000,
    lookahead: state.enabled ? state.lookaheadMs / 1000 : 0,
    model: state.model,
    /** What the hysteresis model is made with, in its manifest's units: it closes the hysteresis under the threshold. */
    modelParams: {
      attack: state.attackMs,
      closeThreshold: state.thresholdDb - state.hysteresisDb,
      hold: state.holdMs,
      lookahead: state.lookaheadMs,
      range: state.floorDb,
      release: state.releaseMs,
      threshold: state.thresholdDb,
    },
    modelWet: state.enabled && !clean ? 1 : 0,
    // Which signal the level is measured on: the key when it is on, the signal itself otherwise.
    outerKey: external ? 1 : 0,
    ownKey: external ? 0 : 1,
    release: state.releaseMs / 1000,
    threshold: toGain(state.thresholdDb),
  };
}

/**
 * The processor of the gate, as the source of an `AudioWorklet`. It reads the
 * key and writes the gain to apply, one value per sample: the level is a peak
 * follower (instant up, a few milliseconds down, so a low note does not make
 * the gate chatter at every zero crossing), the gate is open while the level is
 * over the threshold and for the hold after, and the gain starts at the floor and moves toward 1 or the
 * floor with the attack or the release as a time constant. The engine loads it
 * from a blob, so there is no file to serve.
 */
export const GATE_WORKLET = `
class AudioUiGate extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name: "threshold", defaultValue: 0.016, minValue: 0, maxValue: 1, automationRate: "k-rate" },
      { name: "floor", defaultValue: 0.001, minValue: 0, maxValue: 1, automationRate: "k-rate" },
      { name: "attack", defaultValue: 0.001, minValue: 0.00005, maxValue: 1, automationRate: "k-rate" },
      { name: "hold", defaultValue: 0.03, minValue: 0, maxValue: 5, automationRate: "k-rate" },
      { name: "release", defaultValue: 0.12, minValue: 0.001, maxValue: 10, automationRate: "k-rate" }
    ];
  }
  constructor() {
    super();
    this.level = 0;
    this.gain = -1;
    this.holdLeft = 0;
  }
  process(inputs, outputs, parameters) {
    const key = inputs[0];
    const out = outputs[0][0];
    if (!out) return true;
    const threshold = parameters.threshold[0];
    const floor = parameters.floor[0];
    const holdSamples = parameters.hold[0] * sampleRate;
    const attack = 1 - Math.exp(-1 / (parameters.attack[0] * sampleRate));
    const release = 1 - Math.exp(-1 / (parameters.release[0] * sampleRate));
    const fall = Math.exp(-1 / (0.005 * sampleRate));
    if (this.gain < 0) this.gain = floor;
    for (let n = 0; n < out.length; n += 1) {
      let peak = 0;
      for (let c = 0; c < key.length; c += 1) {
        const v = Math.abs(key[c][n]);
        if (v > peak) peak = v;
      }
      this.level = peak > this.level ? peak : this.level * fall;
      if (this.level >= threshold) this.holdLeft = holdSamples;
      else if (this.holdLeft > 0) this.holdLeft -= 1;
      const target = this.level >= threshold || this.holdLeft > 0 ? 1 : floor;
      this.gain += (target - this.gain) * (target > this.gain ? attack : release);
      out[n] = this.gain;
    }
    return true;
  }
}
registerProcessor("audioui-gate", AudioUiGate);
`;

/** The curve a state plays: the output level in dB for an input level in dB. */
export function gateCurve(state: GateState) {
  if (!state.enabled) {
    return (inputDb: number) => inputDb;
  }
  return (inputDb: number) =>
    inputDb >= state.thresholdDb ? inputDb : inputDb + state.floorDb;
}

/**
 * The source of the hysteresis model's `AudioWorklet`, processor
 * `audioui-gate-hysteresis`: the manifest of `@audio/dynamics-gate`, played
 * by `manifestWorklet`. Every parameter makes it again.
 */
export const GATE_HYSTERESIS_WORKLET = manifestWorklet({
  kernels: GATE_KERNELS,
  models: { hysteresis: "gate" },
  processor: "audioui-gate-hysteresis",
});

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `timeCoef`, as `module0`
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `envelope`, as `module1`
 * - `@audio/dynamics-gate` 0.1.7 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `timeCoef`, as `module2`
 * - `@audio/dynamics-gate` 0.1.7 (MIT, Dmitry Iv.): `gateStream`, as `module3`
 * - `@audio/dynamics-gate` 0.1.7 (MIT, Dmitry Iv.): `gate`
 */
export const GATE_KERNELS = `const module0 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// One-pole smoothing coefficient: y[n] = c·y[n-1] + (1-c)·x[n]. ms → coefficient.
function timeCoef(ms, sampleRate) {
  if (ms <= 0) return 0
  return Math.exp(-1 / (ms * 0.001 * sampleRate))
}

return { timeCoef };
})();

const module1 = (() => {
const { timeCoef } = module0;

// Branching one-pole envelope follower. Returns a stateful per-sample detector.
// Separate attack and release time constants; the classic feed-forward compressor
// topology. Peak or RMS detection selectable.
function envelope(opts = {}) {
  // sampleRate is this family's documented key; fs accepted too — half the ecosystem
  // (and dynamics' own fs-named atoms: multiband, leveler, transient-shaper) passes fs,
  // and silently falling back to 44100 skews ballistics at any other rate.
  let sr = opts.sampleRate ?? opts.fs ?? 44100
  let aa = timeCoef(opts.attack ?? 5, sr)
  let ar = timeCoef(opts.release ?? 50, sr)
  let detector = opts.detector || 'peak'
  let rmsWin = Math.max(1, opts.rmsWindow || 256)

  let rmsBuf = detector === 'rms' ? new Float32Array(rmsWin) : null
  let rmsSum = 0
  let rmsIdx = 0
  let env = 0

  return function detect(x) {
    let mag
    if (detector === 'rms') {
      let sq = x * x
      rmsSum += sq - rmsBuf[rmsIdx]
      rmsBuf[rmsIdx] = sq
      rmsIdx = (rmsIdx + 1) % rmsWin
      mag = Math.sqrt(Math.max(0, rmsSum / rmsWin))
    } else {
      mag = x < 0 ? -x : x
    }
    let c = mag > env ? aa : ar
    env = c * env + (1 - c) * mag
    return env
  }
}

return { envelope };
})();

const module2 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// Wrap { write, flush } into a single callable: write(chunk) → process, write() → flush.
function writer(s) {
  return (chunk) => chunk ? s.write(chunk) : s.flush()
}

function concat(a, b) {
  if (!b || !b.length) return a
  if (!a.length) return b
  let out = new Float32Array(a.length + b.length)
  out.set(a)
  out.set(b, a.length)
  return out
}

const db2lin = (db) => Math.pow(10, db / 20)

// One-pole smoothing coefficient: y[n] = c·y[n-1] + (1-c)·x[n]. ms → coefficient.
function timeCoef(ms, sampleRate) {
  if (ms <= 0) return 0
  return Math.exp(-1 / (ms * 0.001 * sampleRate))
}

return { writer, concat, db2lin, timeCoef };
})();

const module3 = (() => {
const { envelope } = module1;
const { writer, concat, db2lin, timeCoef } = module2;

// Noise gate with hysteresis, hold-then-close logic, look-ahead and smoothed
// gain transitions. The trigger envelope opens above \`threshold\` and, once
// open, only closes below \`closeThreshold\` (hysteresis prevents chatter near
// a single threshold); \`hold\` ms keeps the gate open after the level drops;
// attack/release smooth the gain trajectory. \`lookahead\` delays emission
// behind detection so the gate is already opening when a transient reaches
// the output — batch calls stay sample-aligned (write + flush covers the full
// signal, no silence prefix, no dropped tail); per-block hosts get the delay
// declared as latency (see audio.js).
function gate(data, opts) {
  if (!(data instanceof Float32Array)) return writer(gateStream(data))
  let s = gateStream(opts)
  return concat(s.write(data), s.flush())
}

function gateStream(opts = {}) {
  let sr = opts.sampleRate || 44100
  let threshold = opts.threshold ?? -40
  let closeThreshold = Math.min(opts.closeThreshold ?? threshold - 6, threshold)
  let range = opts.range ?? -60
  let hold = opts.hold ?? 10
  let attackMs = opts.attack ?? 0.1
  let releaseMs = opts.release ?? 100
  let lookahead = opts.lookahead ?? 0

  // Fast envelope drives the trigger; separate coefficients smooth the gate gain.
  let env = envelope({ sampleRate: sr, attack: 0.1, release: 5, detector: opts.detector })
  let openLin = db2lin(threshold)
  let closeLin = db2lin(closeThreshold)
  let closedLin = db2lin(range)
  let aa = timeCoef(attackMs, sr)
  let ar = timeCoef(releaseMs, sr)
  let holdSamp = Math.max(0, Math.round(hold * 0.001 * sr))
  let laSamp = Math.max(0, Math.round(lookahead * 0.001 * sr))

  let g = closedLin
  let held = 0
  let open = false
  let buf = laSamp ? new Float32Array(laSamp) : null
  let bi = 0, pending = 0

  // Detection consumes the incoming sample; with look-ahead, emission returns a
  // sample laSamp behind it scaled by the *current* gain — the gate state at
  // emission already reflects material laSamp ahead, so attacks open in time.
  function step(x) {
    let e = env(x)
    let target
    if (e > openLin) { open = true; held = holdSamp; target = 1 }
    else if (held > 0) { held--; target = 1 }
    else if (open && e > closeLin) target = 1     // hysteresis band: stay open
    else { open = false; target = closedLin }
    let c = target > g ? aa : ar
    g = c * g + (1 - c) * target
    if (!laSamp) return x * g
    if (pending < laSamp) { buf[bi] = x; bi = (bi + 1) % laSamp; pending++; return }
    let y = buf[bi] * g
    buf[bi] = x
    bi = (bi + 1) % laSamp
    return y
  }

  return {
    write(chunk) {
      let out = new Float32Array(chunk.length)
      let o = 0
      for (let i = 0; i < chunk.length; i++) {
        let y = step(chunk[i])
        if (y !== undefined) out[o++] = y
      }
      return o === chunk.length ? out : out.subarray(0, o)
    },
    flush() {
      let out = new Float32Array(pending)
      let o = 0
      while (o < out.length) {
        let y = step(0)
        if (y !== undefined) out[o++] = y
      }
      pending = 0
      return out
    }
  }
}

return { gateStream };
})();

const gate = (() => {
const { gateStream } = module3;
// atom manifest — wraps the dynamics gate kernel per @audio/compile CONTRACT.
// The gate state machine (hysteresis, hold, trigger envelope, gain smoothing,
// look-ahead delay line) lives in gateStream; all params seed it at construction
// (flags: restart). With lookahead > 0 the delay line emits late — declared
// latency lets the host compensate (limiter pattern: short emissions during
// delay-line fill land at the block tail).

const gate = (ctx) => {
	const streams = []
	const opts = {
		sampleRate: ctx.sampleRate,
		threshold: ctx.params.threshold[0],
		closeThreshold: ctx.params.closeThreshold[0],
		range: ctx.params.range[0],
		hold: ctx.params.hold[0],
		attack: ctx.params.attack[0],
		release: ctx.params.release[0],
		lookahead: ctx.params.lookahead[0],
	}
	for (let c = 0, N = ctx.maxChannels ?? 8; c < N; c++) streams.push(gateStream(opts))
	return (inputs, outputs) => {
		const inp = inputs[0], out = outputs[0]
		if (!inp || !inp.length) return
		for (let c = 0; c < inp.length; c++) {
			const w = streams[c].write(inp[c]), y = out[c]
			if (w.length === y.length) y.set(w)
			else { y.fill(0, 0, y.length - w.length); y.set(w, y.length - w.length) }
		}
	}
}
gate.channels = 'any'
gate.latency = (ctx) => Math.round(ctx.params.lookahead[0] * 0.001 * ctx.sampleRate)
gate.tail = 0
gate.params = {
	threshold:      { type: 'number', min: -80, max: 0, default: -40, unit: 'dB', flags: ['restart'] },
	closeThreshold: { type: 'number', min: -90, max: 0, default: -46, unit: 'dB', flags: ['restart'] },
	range:          { type: 'number', min: -90, max: 0, default: -60, unit: 'dB', flags: ['restart'] },
	hold:           { type: 'number', min: 0, max: 500, default: 10, unit: 'ms', flags: ['restart'] },
	attack:         { type: 'number', min: 0.01, max: 100, default: 0.1, unit: 'ms', flags: ['restart'] },
	release:        { type: 'number', min: 1, max: 1000, default: 100, unit: 'ms', flags: ['restart'] },
	lookahead:      { type: 'number', min: 0, max: 50, default: 0, unit: 'ms', flags: ['restart'] },
}

return gate;
})();
`;
